namespace VeskaFlow.Web.Services;

/// <summary>
/// The platform owner's walkthroughs: step by step scripts for showing VeskaFlow to a new client and for setting up a shop with them. Each step says where
/// to go and what to say or show. They are not ticked (the same walkthrough is run again for every client). Only the platform owner sees them, at
/// <c>/Platform/Walkthroughs</c>. English, like every other text; it describes only what the system really does, so change a walkthrough in the same
/// commit as the feature it describes.
/// </summary>
public static class WalkthroughGuide
{
    public static readonly IReadOnlyList<PilotSection> Sections =
    [
        new("w-demo", "1. A 10-minute demo for a new client",
            "Use a demo shop of your own (a few services, two staff, hours set) and have it open on your phone and on a laptop. Show the customer's side first, then the owner's.",
            [
                new("w-demo-1", "Open the shop's booking page on the phone",
                    "Where: /b/ and the shop's address name (Settings shows it).\nSay: This is what your customers see. No app and no account. You put this link on your Facebook page, in your bio, on the door as a QR code."),
                new("w-demo-2", "Pick a service, a person, a day and a time",
                    "Where: the booking page.\nShow: only free times are listed, and a time that is taken disappears. A person with no free time that day is marked 'No free time'.\nSay: Times come from your staff hours, your opening hours and your closed days. Nobody can double-book."),
                new("w-demo-3", "Book as a customer",
                    "Where: type a name and a mobile number, press Confirm booking, answer the question.\nShow: the booking page with the customer's own link (Copy link, Add to calendar, Move booking, Cancel booking).\nSay: The customer keeps this link. They can move or cancel by themselves until your cut-off time, so you get fewer phone calls."),
                new("w-demo-4", "Switch to the owner's side: the day's bookings",
                    "Where: sign in, Bookings (/Admin).\nShow: the new booking in today's or that day's list, with the customer's number you can tap to call.\nSay: Everything for the day is here. Staff with their own login see only their own bookings."),
                new("w-demo-5", "Show Walk-in",
                    "Where: Walk-in (/Admin/WalkIn).\nShow: choose a service and a person, pick a free time, type a name and a number.\nSay: For customers who just arrive. It holds the time like any booking, so the online page never double-books it."),
                new("w-demo-6", "Finish a visit",
                    "Where: Bookings, a booking of today, Mark completed.\nShow: After the visit: add extra services done, set the payment.\nSay: This is how your sales for the day add up."),
                new("w-demo-7", "Show Reports",
                    "Where: Reports.\nShow: revenue, completed bookings and no-shows for the period.\nSay: You see how the shop is doing without a notebook."),
