                new("w-pay-2", "The client pays and says so",
                    "Where: Plan and billing, the GCash details or QR you set.\nDo: they pay, type the reference number and press 'I paid'.\nSay: I confirm it when I see it in my GCash, usually the same day."),
                new("w-pay-3", "You confirm",
                    "Where: Platform, Payments (you).\nDo: check the amount and the reference against your GCash, then confirm. Access, extra staff or the add-on start and the client's page shows the new end date.\nTell them: paying again before the end adds to the end date."),
            ], Tickable: false),
        new("w-msgr", "6. The Messenger assistant (testers only for now)",
