                new("w-mail-2", "Ask customers to confirm by email",
                    "Where: Settings, 'Require email confirmation to book'.\nSay: The booking is held until the customer presses the link we email. It stops fake bookings, but it needs an email from the customer and the email service. Use it only if the shop has a problem with fakes."),
                new("w-mail-3", "Watch the limit",
                    "Where: Platform page, the day's email count.\nSay to yourself: the free email plan is 300 a day for everyone; near 250 it is time to upgrade."),
